package com.securevault.controller;
import com.securevault.entity.*;import com.securevault.repository.UserRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @CrossOrigin(origins="http://localhost:5173") @PreAuthorize("hasRole('ADMINISTRATOR')") public class AdminController{private final UserRepository users;public AdminController(UserRepository u){users=u;}@GetMapping("/users")public List<UserView> users(){return users.findAll().stream().map(u->new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.isMfaEnabled())).toList();}@PatchMapping("/users/{id}/role")public UserView role(@PathVariable Long id,@RequestParam Role role){User u=users.findById(id).orElseThrow();u.setRole(role);users.save(u);return new UserView(u.getId(),u.getName(),u.getEmail(),u.getRole().name(),u.isMfaEnabled());}record UserView(Long id,String name,String email,String role,boolean mfaEnabled){}}
